// This file is generated by AI.

// 未保存更改确认流程: 关闭单个文档/退出项目/退出程序前统一弹窗询问。

import { fs } from './lib/fs';
import { useAppStore } from './state/store';

interface PendingClose {
  action: () => void;
  /** 待关闭的文档路径; `null` 表示关闭全部 (退出项目/程序)。 */
  path: string | null;
}

let pendingClose: PendingClose | null = null;

/** 存在未保存更改时弹窗确认; 否则直接执行 action。
 *
 * 传入 `path` 时只检查该文档 (关闭单个选项卡);
 * 不传时检查全部文档 (关闭项目/退出程序)。
 */
export function confirmClose(action: () => void, path?: string): void {
  const store = useAppStore.getState();
  const dirty =
    path !== undefined ? store.documents.some((d) => d.path === path && d.dirty) : store.documents.some((d) => d.dirty);
  if (!dirty) {
    action();
    return;
  }
  pendingClose = { action, path: path ?? null };
  store.setUnsavedDialog(true);
}

/** 保存 `path` 指定的文档; `path === null` 时保存全部脏文档。 */
async function saveDirty(path: string | null): Promise<void> {
  const store = useAppStore.getState();
  for (const doc of store.documents) {
    if (path !== null && doc.path !== path) continue;
    if (!doc.dirty) continue;
    try {
      await fs.writeText(doc.path, doc.content);
      useAppStore.getState().updateDocument(doc.path, { content: doc.content, dirty: false });
    } catch (e) {
      console.error('保存失败', doc.path, e);
    }
  }
}

export function resolveUnsaved(choice: 'save' | 'discard' | 'cancel'): void {
  const pending = pendingClose;
  pendingClose = null;
  useAppStore.getState().setUnsavedDialog(false);
  if (choice === 'cancel' || !pending) return;
  if (choice === 'save') {
    void saveDirty(pending.path).then(pending.action);
  } else {
    pending.action();
  }
}
